import Foundation

/// Maps a MAC address to the company that registered it.
///
/// Discovery uses this for two things. It names a device before anything has
/// answered a protocol probe — "Caméra Hikvision" rather than "192.168.1.47" —
/// and it rescues cameras that keep every port shut to an unauthenticated
/// stranger, which several vendors do by default: the address resolution table
/// still proves the device is there, and the prefix says what it is.
///
/// Prefixes come from the IEEE registry (via nmap's `nmap-mac-prefixes`), and
/// are matched longest-first because IEEE hands out 24-, 28- and 36-bit blocks:
/// a small vendor's 36-bit assignment lives inside a 24-bit block belonging to
/// the company that resells it.
enum MACVendors {

    struct Match: Equatable {
        let name: String
        /// True when the company sells nothing but cameras and recorders. Such a
        /// device is worth showing on the strength of its address alone; a
        /// TP-Link or a Xiaomi is far more likely to be a plug or a speaker, so
        /// the name is used as a label but never as evidence.
        let makesOnlyCameras: Bool
    }

    /// `nil` for an unregistered or locally administered address — every
    /// randomised phone address lands here, which is the correct answer.
    static func lookup(_ mac: String) -> Match? {
        let digits = mac.uppercased().filter(\.isHexDigit)
        guard digits.count == 12 else { return nil }
        // Longest first: 36-bit assignment, then 28-bit, then the 24-bit OUI.
        for length in [9, 7, 6] {
            if let match = table[String(digits.prefix(length))] { return match }
        }
        return nil
    }

    // MARK: - Table

    private static let table: [String: Match] = {
        var result: [String: Match] = [:]
        for (blob, cameraOnly) in [(cameraVendors, true), (mixedVendors, false)] {
            for line in blob.split(separator: "\n") {
                let parts = line.split(separator: "|", maxSplits: 1)
                guard parts.count == 2 else { continue }
                let match = Match(name: String(parts[0]), makesOnlyCameras: cameraOnly)
                for prefix in parts[1].split(separator: ",") {
                    result[String(prefix)] = match
                }
            }
        }
        return result
    }()

